// ═══ FIREBASE STORAGE IMAGE URL ═══
const PLOT_IMG=(ref)=>`https://firebasestorage.googleapis.com/v0/b/jordan-land.firebasestorage.app/o/plots%2F${ref}.jpg?alt=media`;


// ═══ LOAD LEAFLET CSS & JS DYNAMICALLY ═══
function useLeaflet(){
  const [ready,setReady]=useState(false);
  useEffect(()=>{
    if(window.L&&window.L.markerClusterGroup){setReady(true);return;}
    const loadCSS=(url)=>{const l=document.createElement("link");l.rel="stylesheet";l.href=url;document.head.appendChild(l);};
    const loadJS=(url)=>new Promise(res=>{const s=document.createElement("script");s.src=url;s.onload=res;document.head.appendChild(s);});
    loadCSS("https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css");
    loadCSS("https://cdnjs.cloudflare.com/ajax/libs/leaflet.markercluster/1.5.3/MarkerCluster.css");
    loadCSS("https://cdnjs.cloudflare.com/ajax/libs/leaflet.markercluster/1.5.3/MarkerCluster.Default.css");
    loadJS("https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js").then(()=>
      loadJS("https://cdnjs.cloudflare.com/ajax/libs/leaflet.markercluster/1.5.3/leaflet.markercluster.js").then(()=>setReady(true))
    );
  },[]);
  return ready;
}

// ═══ BUILD POPUP HTML ═══
function buildPopupHTML(lot){
  const pk=lot.plotKey!=null?String(lot.plotKey).padStart(15,"0"):"—";
  const imgUrl=PLOT_IMG(lot.ref);
  return `<div style="direction:rtl;text-align:right;font-family:'Segoe UI',Tahoma,sans-serif;min-width:240px;max-width:300px;padding:2px">
    <img src="${imgUrl}" alt="" onerror="this.style.display='none'" style="width:100%;height:120px;object-fit:cover;border-radius:8px;margin-bottom:8px"/>
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
      <span style="font-weight:800;color:#16a34a;font-size:18px">#${lot.ref}</span>
      <span style="font-size:11px;color:#475569;background:#f1f5f9;padding:2px 8px;border-radius:6px">${lot.area?.toLocaleString()||"—"} م²</span>
    </div>
    <div style="font-size:12.5px;color:#1e293b;line-height:1.9;text-align:right">
      <div><span style="color:#16a34a;font-weight:600">المحافظة:</span> ${lot.gov}</div>
      <div><span style="color:#16a34a;font-weight:600">المديرية:</span> ${lot.dist}</div>
      <div><span style="color:#16a34a;font-weight:600">القرية:</span> ${lot.village}</div>
      <div><span style="color:#16a34a;font-weight:600">الحوض:</span> ${lot.basin}</div>
      <div><span style="color:#16a34a;font-weight:600">الحي:</span> ${lot.hood||"—"}</div>
      ${lot.propType?`<div><span style="color:#16a34a;font-weight:600">نوع العقار:</span> <span style="background:#3b82f620;color:#3b82f6;padding:1px 6px;border-radius:4px;font-weight:600">${lot.propType}</span></div>`:""}
    </div>
    <div style="margin-top:8px;padding-top:8px;border-top:1px solid #e2e8f0;font-size:12.5px;color:#1e293b;line-height:1.9;text-align:right">
      <div><span style="color:#d97706;font-weight:600">رقم القطعة:</span> ${lot.plot||"—"}</div>
      <div><span style="color:#d97706;font-weight:600">مفتاح القطعة:</span> <span style="direction:ltr;display:inline-block;background:#f1f5f9;padding:1px 6px;border-radius:4px;font-family:monospace;font-size:12px;color:#334155">${pk}</span></div>
      ${lot.adminPrice?`<div><span style="color:#d97706;font-weight:600">السعر الإداري:</span> ${lot.adminPrice}</div>`:""}
      <div><span style="color:#d97706;font-weight:600">المالك:</span> ${lot.owner||"—"}</div>
      ${lot.share?`<div><span style="color:#d97706;font-weight:600">الحصة:</span> ${lot.share}</div>`:""}
    </div>
    <div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap;direction:rtl;justify-content:flex-start">
      ${lot.mapUrl?`<a href="${lot.mapUrl}" target="_blank" rel="noopener noreferrer" style="display:inline-block;padding:6px 12px;background:#16a34a;color:#fff;border-radius:8px;text-decoration:none;font-weight:700;font-size:11px">🗺️ فتح الموقع</a>`:""}
      <a href="https://wa.link/e3hzg4" target="_blank" rel="noopener noreferrer" style="display:inline-block;padding:6px 12px;background:#25d366;color:#fff;border-radius:8px;text-decoration:none;font-weight:700;font-size:11px">💬 واتساب</a>
    </div>
  </div>`;
}

// ═══ MAP COMPONENT ═══
function MapView({lots,onBoundsChange,selectedRef,onSelect}){
  const mapRef=useRef(null);
  const mapInst=useRef(null);
  const clusterRef=useRef(null);
  const markersRef=useRef({});
  const leafletReady=useLeaflet();

  useEffect(()=>{
    if(!leafletReady||!mapRef.current||mapInst.current)return;
    const L=window.L;
    const map=L.map(mapRef.current,{zoomControl:true,attributionControl:false}).fitBounds([[29.18,34.95],[33.38,39.30]],{padding:[10,10]});

    // Tile layers - using reliable free providers
    const streets=L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:""});
    const satellite=L.tileLayer("https://mt{s}.google.com/vt/lyrs=s&x={x}&y={y}&z={z}",{maxZoom:20,subdomains:"0123",attribution:""});
    const terrain=L.tileLayer("https://mt{s}.google.com/vt/lyrs=p&x={x}&y={y}&z={z}",{maxZoom:20,subdomains:"0123",attribution:""});
    streets.addTo(map);
    L.control.layers({"خريطة":streets,"قمر صناعي":satellite,"تضاريس":terrain},{},{position:"topright",collapsed:true}).addTo(map);

    const cluster=L.markerClusterGroup({maxClusterRadius:50,spiderfyOnMaxZoom:true,showCoverageOnHover:false,
      iconCreateFunction:function(c){const count=c.getChildCount();let size="small",r=30;if(count>10){size="medium";r=40;}if(count>25){size="large";r=50;}
        return L.divIcon({html:"<div style='background:linear-gradient(135deg,#22c55e,#16a34a);color:#fff;border-radius:50%;width:"+r+"px;height:"+r+"px;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:"+(r>35?16:13)+"px;box-shadow:0 3px 12px rgba(34,197,94,0.4);border:2px solid #fff'>"+count+"</div>",className:"",iconSize:[r,r]});}
    });

    map.addLayer(cluster);
    clusterRef.current=cluster;
    mapInst.current=map;

    // Notify parent on move
    const notifyBounds=()=>{
      if(!onBoundsChange)return;
      const b=map.getBounds();
      onBoundsChange({north:b.getNorth(),south:b.getSouth(),east:b.getEast(),west:b.getWest()});
    };
    map.on("moveend",notifyBounds);
    setTimeout(notifyBounds,500);

    return()=>{map.remove();mapInst.current=null;};
  },[leafletReady]);

  // Rebuild markers only when filtered lots change
  useEffect(()=>{
    if(!mapInst.current||!clusterRef.current||!leafletReady)return;
    const L=window.L;
    const cluster=clusterRef.current;
    cluster.clearLayers();
    const coordMap={};
    COORDS.forEach(c=>{coordMap[c[0]]={lat:c[1],lng:c[2]};});
    const newMarkers={};
    lots.forEach(lot=>{
      const co=coordMap[lot.ref];
      if(!co)return;
      const marker=L.circleMarker([co.lat,co.lng],{radius:9,fillColor:"#22c55e",color:"#fff",weight:2,opacity:1,fillOpacity:0.85});
      marker.bindPopup(buildPopupHTML(lot),{maxWidth:320});
      marker.on("click",()=>{if(onSelect)onSelect(lot.ref);});
      cluster.addLayer(marker);
      newMarkers[lot.ref]=marker;
    });
    markersRef.current=newMarkers;
  },[lots,leafletReady]);

  // Handle selection highlight without rebuilding markers
  useEffect(()=>{
    if(!markersRef.current||!Object.keys(markersRef.current).length)return;
    // Reset all markers to default style
    Object.values(markersRef.current).forEach(m=>{
      m.setStyle({radius:9,fillColor:"#22c55e",weight:2});
    });
    // Highlight selected
    if(selectedRef){
      const sel=markersRef.current[selectedRef];
      if(sel){
        sel.setStyle({radius:13,fillColor:"#f59e0b",weight:3});
      }
    }
  },[selectedRef]);

  if(!leafletReady)return <div style={{display:"flex",alignItems:"center",justifyContent:"center",height:"100%",background:C.bg,color:C.textDim}}>جاري تحميل الخريطة...</div>;
  return <div ref={mapRef} style={{width:"100%",height:"100%",overflow:"hidden"}}/>;
}

// ═══ MODAL: Add New Plot ═══
function AddPlotModal({open,onClose}){
  const [f,setF]=useState({gov:"",dist:"",village:"",basin:"",hood:"",plot:"",plotKey:"",adminPrice:"",area:"",propType:"",owner:"",share:"",mapUrl:"",pic:""});
  const [img,setImg]=useState(null);
  const fileRef=useRef(null);
  const govOptions=useMemo(()=>HG.map(g=>({label:`${g[0]} (${g[1]})`,value:g[1],name:g[0]})),[]);
  const distOptions=useMemo(()=>{if(!f.gov)return[];const gc=parseInt(f.gov);return HD.filter(d=>d[2]===gc).map(d=>({label:`${d[0]} (${d[1]})`,value:d[1],name:d[0]}));},[f.gov]);
  const villOptions=useMemo(()=>{if(!f.dist)return[];const dc=parseInt(f.dist);return HV.filter(v=>v[2]===dc).map(v=>({label:`${v[0]} (${v[1]})`,value:v[1],name:v[0]}));},[f.dist]);
  const basinOptions=useMemo(()=>{if(!f.village)return[];const vc=parseInt(f.village);return HB.filter(b=>b[2]===vc).map(b=>({label:`${b[0]} (${b[1]})`,value:b[1],name:b[0]}));},[f.village]);
  const hoodOptions=useMemo(()=>{if(!f.village||!f.basin)return[];const vc=parseInt(f.village),bc=parseInt(f.basin);return HH.filter(h=>h[1]===vc&&h[2]===bc).map(h=>({label:h[0],value:h[0]}));},[f.village,f.basin]);
  const set=(k,v)=>{const resets={gov:{dist:"",village:"",basin:"",hood:""},dist:{village:"",basin:"",hood:""},village:{basin:"",hood:""},basin:{hood:""}};setF(prev=>({...prev,[k]:v,...(resets[k]||{})}));};
  const handleImg=(e)=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=(ev)=>setImg(ev.target.result);reader.readAsDataURL(file);};
  const sendWA=()=>{
    const gName=govOptions.find(o=>o.value===parseInt(f.gov))?.label||f.gov;
    const dName=distOptions.find(o=>o.value===parseInt(f.dist))?.label||f.dist;
    const vName=villOptions.find(o=>o.value===parseInt(f.village))?.label||f.village;
    const bName=basinOptions.find(o=>o.value===parseInt(f.basin))?.label||f.basin;
    const lines=["🏗️ *طلب إضافة عقار جديد*","",`📍 المحافظة: ${gName}`,`📍 المديرية: ${dName}`,`📍 القرية: ${vName}`,`📍 الحوض: ${bName}`,`📍 الحي: ${f.hood||"—"}`,`📍 رقم القطعة: ${f.plot||"—"}`,`🔑 مفتاح القطعة: ${f.plotKey?String(f.plotKey).padStart(15,"0"):"—"}`,`💰 السعر الإداري: ${f.adminPrice||"—"}`,`📐 المساحة: ${f.area||"—"} م²`,`🏠 نوع العقار: ${f.propType||"—"}`,`👤 المالك: ${f.owner||"—"}`,`📊 الحصة: ${f.share||"—"}`,`🗺️ الموقع: ${f.mapUrl||"—"}`];
    window.open(`https://wa.me/962776615498?text=${encodeURIComponent(lines.join("\n"))}`,"_blank");
  };
  if(!open)return null;
  const inputStyle={width:"100%",padding:"10px 12px",background:C.inputBg,border:`1px solid ${C.border}`,borderRadius:"8px",color:C.text,fontSize:"14px",outline:"none",direction:"rtl"};
  const selectStyle={...inputStyle,appearance:"none",cursor:"pointer"};
  const labelStyle={fontSize:"13px",color:C.textDim,marginBottom:"4px",display:"block",textAlign:"right"};
  return(
    <div style={{position:"fixed",inset:0,zIndex:1000,background:C.overlay,display:"flex",alignItems:"center",justifyContent:"center",padding:"20px"}} onClick={onClose}>
      <div style={{background:C.card,borderRadius:"16px",border:`1px solid ${C.border}`,width:"100%",maxWidth:"600px",maxHeight:"90vh",overflow:"auto",padding:"24px"}} onClick={e=>e.stopPropagation()}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"20px"}}><button onClick={onClose} style={{background:"none",border:"none",color:C.textDim,fontSize:"24px",cursor:"pointer"}}>✕</button><h2 style={{color:C.accent,fontSize:"20px",margin:0,fontWeight:700}}>إضافة عقار جديد</h2></div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"12px",direction:"rtl"}}>
          <div><label style={labelStyle}>المحافظة *</label><select style={selectStyle} value={f.gov} onChange={e=>set("gov",e.target.value)}><option value="">اختر المحافظة</option>{govOptions.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></div>
          <div><label style={labelStyle}>المديرية *</label><select style={selectStyle} value={f.dist} onChange={e=>set("dist",e.target.value)} disabled={!f.gov}><option value="">اختر المديرية</option>{distOptions.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></div>
          <div><label style={labelStyle}>القرية *</label><select style={selectStyle} value={f.village} onChange={e=>set("village",e.target.value)} disabled={!f.dist}><option value="">اختر القرية</option>{villOptions.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></div>
          <div><label style={labelStyle}>الحوض *</label><select style={selectStyle} value={f.basin} onChange={e=>set("basin",e.target.value)} disabled={!f.village}><option value="">اختر الحوض</option>{basinOptions.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></div>
          <div><label style={labelStyle}>الحي</label><select style={selectStyle} value={f.hood} onChange={e=>set("hood",e.target.value)} disabled={!f.basin}><option value="">اختر الحي</option>{hoodOptions.map((o,i)=><option key={i} value={o.value}>{o.label}</option>)}</select></div>
          <div><label style={labelStyle}>رقم القطعة *</label><input style={inputStyle} value={f.plot} onChange={e=>setF(p=>({...p,plot:e.target.value}))} placeholder="أدخل رقم القطعة"/></div>
          <div><label style={labelStyle}>مفتاح القطعة</label><input style={inputStyle} value={f.plotKey} onChange={e=>setF(p=>({...p,plotKey:e.target.value}))} placeholder="مفتاح القطعة"/></div>
          <div><label style={labelStyle}>السعر الإداري</label><input style={inputStyle} value={f.adminPrice} onChange={e=>setF(p=>({...p,adminPrice:e.target.value}))} placeholder="السعر / م²"/></div>
          <div><label style={labelStyle}>المساحة (م²)</label><input style={inputStyle} type="number" value={f.area} onChange={e=>setF(p=>({...p,area:e.target.value}))} placeholder="المساحة"/></div>
          <div><label style={labelStyle}>نوع العقار</label><select style={selectStyle} value={f.propType} onChange={e=>setF(p=>({...p,propType:e.target.value}))}><option value="">اختر نوع العقار</option><option value="سكني">🏡 سكني</option><option value="تجاري">🏬 تجاري</option><option value="صناعي">🏭 صناعي</option><option value="زراعي">🌾 زراعي</option></select></div>
          <div><label style={labelStyle}>المالك</label><input style={inputStyle} value={f.owner} onChange={e=>setF(p=>({...p,owner:e.target.value}))} placeholder="اسم المالك"/></div>
          <div><label style={labelStyle}>الحصة</label><input style={inputStyle} value={f.share} onChange={e=>setF(p=>({...p,share:e.target.value}))} placeholder="مثال: 1/2"/></div>
          <div style={{gridColumn:"1/-1"}}><label style={labelStyle}>رابط الموقع</label><input style={inputStyle} value={f.mapUrl} onChange={e=>setF(p=>({...p,mapUrl:e.target.value}))} placeholder="رابط خرائط جوجل"/></div>
          <div style={{gridColumn:"1/-1"}}><label style={labelStyle}>صورة القطعة</label><div style={{display:"flex",gap:"8px",alignItems:"center",flexDirection:"row-reverse"}}><button onClick={()=>fileRef.current?.click()} style={{padding:"10px 16px",background:C.accent,color:C.bg,border:"none",borderRadius:"8px",cursor:"pointer",fontWeight:600,fontSize:"13px"}}>📷 اختر صورة</button><input ref={fileRef} type="file" accept="image/*" onChange={handleImg} style={{display:"none"}}/>{img&&<img src={img} alt="preview" style={{height:"50px",borderRadius:"6px",border:`1px solid ${C.border}`}}/>}</div></div>
        </div>
        <div style={{marginTop:"20px",display:"flex",gap:"10px",justifyContent:"flex-start",direction:"rtl"}}><button onClick={sendWA} style={{padding:"12px 24px",background:"#25d366",color:C.white,border:"none",borderRadius:"10px",cursor:"pointer",fontWeight:700,fontSize:"14px"}}>📤 إرسال عبر واتساب</button><button onClick={onClose} style={{padding:"12px 24px",background:C.inputBg,color:C.textDim,border:`1px solid ${C.border}`,borderRadius:"10px",cursor:"pointer",fontSize:"14px"}}>إلغاء</button></div>
      </div>
    </div>
  );
}

// ═══ PLOT CARD ═══
function PlotCard({lot,isSelected,onSelect}){
  const [imgSrc,setImgSrc]=useState(null);
  const [fbImgOk,setFbImgOk]=useState(true);
  const fileRef=useRef(null);
  const cardRef=useRef(null);
  const handleImg=(e)=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=ev=>setImgSrc(ev.target.result);r.readAsDataURL(f);};
  const plotImg=imgSrc||lot.pic||(fbImgOk?PLOT_IMG(lot.ref):null);

  useEffect(()=>{if(isSelected&&cardRef.current)cardRef.current.scrollIntoView({behavior:"smooth",block:"center"});},[isSelected]);

  return(
    <div ref={cardRef} style={{background:isSelected?C.cardHover:C.card,borderRadius:"14px",border:`1px solid ${isSelected?C.accent+"80":C.border}`,transition:"all 0.2s",cursor:"pointer",flexShrink:0}} onClick={()=>{if(onSelect)onSelect(lot.ref);}} onMouseEnter={e=>{e.currentTarget.style.background=C.cardHover;e.currentTarget.style.borderColor=C.accent+"40"}} onMouseLeave={e=>{if(!isSelected){e.currentTarget.style.background=C.card;e.currentTarget.style.borderColor=C.border}}}>
      {plotImg&&<div style={{height:"160px",overflow:"hidden",borderRadius:"14px 14px 0 0"}}><img src={plotImg} alt="" onError={()=>setFbImgOk(false)} style={{width:"100%",height:"100%",objectFit:"cover"}}/></div>}
      <div style={{padding:"14px"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"8px",direction:"rtl"}}>
          <span style={{color:C.accent,fontWeight:800,fontSize:"18px"}}>#{lot.ref}</span>
          <span style={{fontSize:"12px",color:C.textDim,background:C.inputBg,padding:"2px 8px",borderRadius:"6px"}}>{lot.area?.toLocaleString()||"—"} م²</span>
        </div>
        <div style={{direction:"rtl",fontSize:"13px",color:C.textDim,lineHeight:1.8}}>
          <div><span style={{color:C.accent,fontWeight:600}}>المحافظة:</span> {lot.gov}</div>
          <div><span style={{color:C.accent,fontWeight:600}}>المديرية:</span> {lot.dist}</div>
          <div><span style={{color:C.accent,fontWeight:600}}>القرية:</span> {lot.village}</div>
          <div><span style={{color:C.accent,fontWeight:600}}>الحوض:</span> {lot.basin}</div>
          <div><span style={{color:C.accent,fontWeight:600}}>الحي:</span> {lot.hood||"—"}</div>
          {lot.propType&&<div><span style={{color:C.accent,fontWeight:600}}>نوع العقار:</span> <span style={{background:C.blue+"20",color:C.blue,padding:"1px 6px",borderRadius:"4px",fontWeight:600}}>{lot.propType}</span></div>}
        </div>
        <div style={{marginTop:"10px",paddingTop:"10px",borderTop:`1px solid ${C.border}`,direction:"rtl",fontSize:"13px",color:C.textDim,lineHeight:1.8}}>
          <div><span style={{color:C.gold,fontWeight:600}}>رقم القطعة:</span> {lot.plot||"—"}</div>
          <div><span style={{color:C.gold,fontWeight:600}}>مفتاح القطعة:</span> <span onClick={e=>{e.stopPropagation();const t=document.createElement("textarea");t.value=padKey(lot.plotKey);t.style.position="fixed";t.style.opacity="0";document.body.appendChild(t);t.select();document.execCommand("copy");document.body.removeChild(t);const el=e.currentTarget;el.style.color=C.accent;el.textContent="✓ تم النسخ";setTimeout(()=>{el.style.color=C.text;el.textContent=padKey(lot.plotKey)},1200)}} style={{cursor:"pointer",userSelect:"text",direction:"ltr",display:"inline-block",background:C.inputBg,padding:"2px 8px",borderRadius:"4px",fontFamily:"monospace",fontSize:"13px",color:C.text}} title="انقر للنسخ">{padKey(lot.plotKey)}</span></div>
          <div><span style={{color:C.gold,fontWeight:600}}>المساحة:</span> {lot.area?.toLocaleString()||"—"} م²</div>
          {lot.adminPrice&&<div><span style={{color:C.gold,fontWeight:600}}>السعر الإداري:</span> {lot.adminPrice}</div>}
          <div><span style={{color:C.gold,fontWeight:600}}>المالك:</span> {lot.owner||"—"}</div>
          {lot.share&&<div><span style={{color:C.gold,fontWeight:600}}>الحصة:</span> {lot.share}</div>}
        </div>
        <div style={{marginTop:"10px",display:"flex",gap:"6px",flexWrap:"wrap",direction:"rtl"}}>
          {lot.mapUrl&&<a href={lot.mapUrl} target="_blank" rel="noopener noreferrer" onClick={e=>e.stopPropagation()} style={{padding:"6px 14px",background:C.accent,color:C.bg,borderRadius:"8px",textDecoration:"none",fontWeight:600,fontSize:"12px"}}>🗺️ فتح الموقع</a>}
          <a href="https://wa.link/e3hzg4" target="_blank" rel="noopener noreferrer" onClick={e=>e.stopPropagation()} style={{padding:"6px 14px",background:"#25d366",color:C.white,borderRadius:"8px",textDecoration:"none",fontWeight:600,fontSize:"12px"}}>💬 واتساب</a>
          <button onClick={e=>{e.stopPropagation();fileRef.current?.click()}} style={{padding:"6px 14px",background:C.inputBg,color:C.textDim,border:`1px solid ${C.border}`,borderRadius:"8px",cursor:"pointer",fontSize:"12px"}}>📷 رفع صورة</button>
          <input ref={fileRef} type="file" accept="image/*" onChange={handleImg} style={{display:"none"}}/>
        </div>
      </div>
    </div>
  );
}

// ═══ MAIN APP ═══
export default function JordanLand(){
  const [page,setPage]=useState("landing"); // "landing" | "map"
  const [search,setSearch]=useState("");
  const [govFilter,setGovFilter]=useState("");
  const [distFilter,setDistFilter]=useState("");
  const [villFilter,setVillFilter]=useState("");
  const [basinFilter,setBasinFilter]=useState("");
  const [hoodFilter,setHoodFilter]=useState("");
  const [propTypeFilter,setPropTypeFilter]=useState("");
  const [showAdd,setShowAdd]=useState(false);
  const [mobileView,setMobileView]=useState("map"); // "map" | "list"
  const [mapBounds,setMapBounds]=useState(null);
  const [selectedRef,setSelectedRef]=useState(null);
  const [isMobile,setIsMobile]=useState(window.innerWidth<768);

  useEffect(()=>{const h=()=>setIsMobile(window.innerWidth<768);window.addEventListener("resize",h);return()=>window.removeEventListener("resize",h);},[]);

  // Cascading filter data
  const filteredDists=useMemo(()=>{if(!govFilter)return[];const[,gc]=parseNC(govFilter);if(gc===null)return[];return HD.filter(d=>d[2]===gc);},[govFilter]);
  const filteredVills=useMemo(()=>{if(!distFilter)return[];const dc=parseInt(distFilter);return HV.filter(v=>v[2]===dc);},[distFilter]);
  const filteredBasins=useMemo(()=>{if(!villFilter)return[];const vc=parseInt(villFilter);return HB.filter(b=>b[2]===vc);},[villFilter]);
  const filteredHoods=useMemo(()=>{if(!villFilter||!basinFilter)return[];const vc=parseInt(villFilter),bc=parseInt(basinFilter);return HH.filter(h=>h[1]===vc&&h[2]===bc);},[villFilter,basinFilter]);

  // Filter lots by dropdowns + search
  const filtered=useMemo(()=>{
    let res=LOTS;
    if(govFilter){const[,gc]=parseNC(govFilter);if(gc!==null){const gn=HG.find(g=>g[1]===gc);if(gn)res=res.filter(l=>l.gov.includes(gn[0]));}}
    if(distFilter){const dc=parseInt(distFilter);const dn=HD.find(d=>d[1]===dc);if(dn)res=res.filter(l=>l.dist.includes(dn[0]));}
    if(villFilter){const vc=parseInt(villFilter);const vn=HV.find(v=>v[1]===vc);if(vn)res=res.filter(l=>l.village.includes(vn[0]));}
    if(basinFilter){const bc=parseInt(basinFilter);const bn=HB.find(b=>b[1]===bc&&b[2]===parseInt(villFilter));if(bn)res=res.filter(l=>l.basin.includes(bn[0]));}
    if(hoodFilter){res=res.filter(l=>l.hood===hoodFilter);}
    if(propTypeFilter){res=res.filter(l=>l.propType===propTypeFilter);}
    if(search.trim()){const q=search.trim().toLowerCase();res=res.filter(l=>[l.gov,l.dist,l.village,l.basin,l.hood,String(l.plot),padKey(l.plotKey),l.owner,l.adminPrice,String(l.area),l.share,l.propType].some(v=>v&&String(v).toLowerCase().includes(q)));}
    return res;
  },[search,govFilter,distFilter,villFilter,basinFilter,hoodFilter,propTypeFilter]);

  // Further filter by map bounds for the list
  const coordMap=useMemo(()=>{const m={};COORDS.forEach(c=>{m[c[0]]={lat:c[1],lng:c[2]};});return m;},[]);
  const visibleInMap=useMemo(()=>{
    if(!mapBounds)return filtered;
    return filtered.filter(l=>{const co=coordMap[l.ref];if(!co)return false;return co.lat>=mapBounds.south&&co.lat<=mapBounds.north&&co.lng>=mapBounds.west&&co.lng<=mapBounds.east;});
  },[filtered,mapBounds,coordMap]);

  const resetFilters=()=>{setGovFilter("");setDistFilter("");setVillFilter("");setBasinFilter("");setHoodFilter("");setPropTypeFilter("");setSearch("")};
  const goHome=()=>{setPage("landing");resetFilters();setPropTypeFilter("")};

  // ═══ LANDING PAGE ═══
  if(page==="landing"){
    const goTo=(filter)=>{setPropTypeFilter(filter);setPage("map");};

    const landingBtn=(icon,label,filter,desc)=>(
      <button onClick={()=>goTo(filter)} style={{flex:1,minWidth:"140px",padding:"24px 16px",background:C.card,border:`2px solid ${C.border}`,borderRadius:"16px",cursor:"pointer",transition:"all 0.2s",display:"flex",flexDirection:"column",alignItems:"center",gap:"10px"}}
        onMouseEnter={e=>{e.currentTarget.style.borderColor=C.accent;e.currentTarget.style.background=C.cardHover;e.currentTarget.style.transform="translateY(-4px)";e.currentTarget.style.boxShadow=`0 8px 24px ${C.accent}20`}}
        onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.background=C.card;e.currentTarget.style.transform="translateY(0)";e.currentTarget.style.boxShadow="none"}}>
        <span style={{fontSize:"40px"}}>{icon}</span>
        <span style={{color:C.text,fontWeight:700,fontSize:"18px"}}>{label}</span>
        {desc&&<span style={{color:C.textDim,fontSize:"12px",lineHeight:1.4}}>{desc}</span>}
      </button>
    );

    return(
      <div style={{minHeight:"100vh",background:C.bg,fontFamily:"'Segoe UI',Tahoma,sans-serif",color:C.text,display:"flex",flexDirection:"column",alignItems:"center"}}>
        {/* Header */}
        <div style={{width:"100%",background:"linear-gradient(135deg,#0d1f3c 0%,#162a4a 50%,#0a1628 100%)",borderBottom:`1px solid ${C.border}`,padding:"32px 20px",textAlign:"center"}}>
          <h1 style={{margin:0,fontSize:"32px",fontWeight:800,color:C.white}}><img src={JO_FLAG} alt="🇯🇴" style={{height:"1em",verticalAlign:"middle",marginLeft:"8px",borderRadius:"2px"}}/> عقارات الأردن</h1>
          <p style={{margin:"8px 0 0",color:C.textDim,fontSize:"16px"}}>منصة العقارات الأردنية</p>
        </div>

        <div style={{width:"100%",maxWidth:"800px",padding:"40px 20px",direction:"rtl"}}>
          <h2 style={{color:C.text,fontSize:"20px",fontWeight:700,marginBottom:"24px",textAlign:"center"}}>اختر نوع العقار</h2>
          <div style={{display:"flex",gap:"14px",justifyContent:"center",flexWrap:"wrap"}}>
            {landingBtn("🔄","عرض الكل","","عرض جميع العقارات")}
            {landingBtn("🏡","سكني","سكني","شقق، فلل، أراضي سكنية")}
            {landingBtn("🏬","تجاري","تجاري","أراضي، مكاتب، محلات، مجمعات")}
            {landingBtn("🏭","صناعي","صناعي","أراضي، مصانع، مستودعات، ورش")}
            {landingBtn("🌾","زراعي","زراعي","أراضي زراعية، مزارع")}
          </div>
        </div>
      </div>
    );
  }

  // ═══ MAP PAGE ═══
  const selectStyle={padding:"10px 14px",background:C.inputBg,border:`1px solid ${C.border}`,borderRadius:"10px",color:C.text,fontSize:"14px",direction:"rtl",outline:"none",cursor:"pointer",appearance:"none",width:"100%"};

  return(
    <div style={{height:"100vh",background:C.bg,fontFamily:"'Segoe UI',Tahoma,sans-serif",color:C.text,display:"flex",flexDirection:"column",overflow:"hidden"}}>
      {/* Header */}
      <div style={{background:"linear-gradient(135deg,#0d1f3c 0%,#162a4a 50%,#0a1628 100%)",borderBottom:`1px solid ${C.border}`,padding:"14px 20px",flexShrink:0}}>
        <div style={{maxWidth:"1800px",margin:"0 auto",display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:"10px"}}>
          <div style={{display:"flex",gap:"8px",alignItems:"center",flexWrap:"wrap"}}>
            <button onClick={goHome} style={{padding:"10px 20px",background:"linear-gradient(135deg,#3b82f6,#2563eb)",color:C.white,border:"none",borderRadius:"10px",cursor:"pointer",fontWeight:700,fontSize:"14px",boxShadow:"0 4px 15px rgba(59,130,246,0.3)"}}>🏠 الرئيسية</button>
            <button onClick={()=>setShowAdd(true)} style={{padding:"10px 20px",background:`linear-gradient(135deg,${C.accent},${C.accentDark})`,color:C.white,border:"none",borderRadius:"10px",cursor:"pointer",fontWeight:700,fontSize:"14px",boxShadow:`0 4px 15px ${C.accent}30`}}>+ إضافة عقار</button>
            <a href="https://wa.link/e3hzg4" target="_blank" rel="noopener noreferrer" style={{padding:"10px 20px",background:"linear-gradient(135deg,#25d366,#128c7e)",color:C.white,border:"none",borderRadius:"10px",cursor:"pointer",fontWeight:700,fontSize:"14px",textDecoration:"none",boxShadow:"0 4px 15px rgba(37,211,102,0.3)"}}>💬 تواصل معنا</a>
          </div>
          <div style={{display:"flex",alignItems:"center",gap:"12px"}}>
            <div style={{display:"flex",gap:"4px",direction:"rtl",flexWrap:"wrap"}}>
              <button onClick={()=>setPropTypeFilter("")} style={{padding:"4px 10px",background:!propTypeFilter?C.accent+"30":"transparent",border:`1px solid ${!propTypeFilter?C.accent:C.border}`,borderRadius:"8px",color:!propTypeFilter?C.accent:C.textDim,cursor:"pointer",fontSize:"12px",fontWeight:600,transition:"all 0.2s"}}>🔄 عرض الكل</button>
              {[{v:"سكني",i:"🏡"},{v:"تجاري",i:"🏬"},{v:"صناعي",i:"🏭"},{v:"زراعي",i:"🌾"}].map(t=>(
                <button key={t.v} onClick={()=>setPropTypeFilter(propTypeFilter===t.v?"":t.v)} style={{padding:"4px 10px",background:propTypeFilter===t.v?C.accent+"30":"transparent",border:`1px solid ${propTypeFilter===t.v?C.accent:C.border}`,borderRadius:"8px",color:propTypeFilter===t.v?C.accent:C.textDim,cursor:"pointer",fontSize:"12px",fontWeight:600,transition:"all 0.2s"}}>{t.i} {t.v}</button>
              ))}
            </div>
            <div style={{textAlign:"right"}}>
              <h1 style={{margin:0,fontSize:"22px",fontWeight:800,color:C.white}}><img src={JO_FLAG} alt="🇯🇴" style={{height:"1em",verticalAlign:"middle",marginLeft:"8px",borderRadius:"2px"}}/> عقارات الأردن</h1>
              <p style={{margin:"2px 0 0",color:C.textDim,fontSize:"12px"}}>{filtered.length} قطعة عقار</p>
            </div>
          </div>
        </div>
      </div>

      {/* Mobile toggle */}
      {isMobile&&(
        <div style={{display:"flex",gap:0,padding:"0",flexShrink:0,borderBottom:`1px solid ${C.border}`}}>
          <button onClick={()=>setMobileView("map")} style={{flex:1,padding:"12px",background:mobileView==="map"?C.accent:C.card,color:mobileView==="map"?C.bg:C.textDim,border:"none",fontWeight:700,fontSize:"14px",cursor:"pointer"}}>🗺️ الخريطة</button>
          <button onClick={()=>setMobileView("list")} style={{flex:1,padding:"12px",background:mobileView==="list"?C.accent:C.card,color:mobileView==="list"?C.bg:C.textDim,border:"none",fontWeight:700,fontSize:"14px",cursor:"pointer"}}>📋 القائمة ({visibleInMap.length})</button>
        </div>
      )}

      {/* Main content: split view - takes remaining height */}
      <div style={{flex:1,display:"flex",overflow:"hidden",minHeight:0,direction:"ltr"}}>
        {/* MAP */}
        {(!isMobile||mobileView==="map")&&(
          <div style={{flex:isMobile?1:1.2,position:"relative",height:"100%"}}>
            <MapView lots={filtered} onBoundsChange={setMapBounds} selectedRef={selectedRef} onSelect={setSelectedRef}/>
          </div>
        )}

        {/* LIST PANEL */}
        {(!isMobile||mobileView==="list")&&(
          <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden",height:"100%",borderLeft:isMobile?"none":`1px solid ${C.border}`}}>
            {/* Filters */}
            <div style={{padding:"10px 12px",borderBottom:`1px solid ${C.border}`,flexShrink:0,overflowY:"auto",maxHeight:"200px"}}>
              <div style={{display:"flex",flexDirection:"column",gap:"8px"}}>
                <select style={selectStyle} value={govFilter} onChange={e=>{setGovFilter(e.target.value);setDistFilter("");setVillFilter("");setBasinFilter("");setHoodFilter("")}}><option value="">كل المحافظات</option>{HG.map(g=><option key={g[1]} value={`${g[0]} (${g[1]})`}>{g[0]} ({g[1]})</option>)}</select>
                <select style={selectStyle} value={distFilter} onChange={e=>{setDistFilter(e.target.value);setVillFilter("");setBasinFilter("");setHoodFilter("")}} disabled={!govFilter}><option value="">كل المديريات</option>{filteredDists.map(d=><option key={d[1]} value={d[1]}>{d[0]} ({d[1]})</option>)}</select>
                <select style={selectStyle} value={villFilter} onChange={e=>{setVillFilter(e.target.value);setBasinFilter("");setHoodFilter("")}} disabled={!distFilter}><option value="">كل القرى</option>{filteredVills.map(v=><option key={v[1]} value={v[1]}>{v[0]} ({v[1]})</option>)}</select>
                <select style={selectStyle} value={basinFilter} onChange={e=>{setBasinFilter(e.target.value);setHoodFilter("")}} disabled={!villFilter}><option value="">كل الأحواض</option>{filteredBasins.map((b,i)=><option key={i} value={b[1]}>{b[0]} ({b[1]})</option>)}</select>
                <select style={selectStyle} value={hoodFilter} onChange={e=>setHoodFilter(e.target.value)} disabled={!basinFilter}><option value="">كل الأحياء</option>{filteredHoods.map((h,i)=><option key={i} value={h[0]}>{h[0]}</option>)}</select>
                {(govFilter||distFilter||villFilter||basinFilter||hoodFilter||propTypeFilter||search)&&<button onClick={resetFilters} style={{padding:"8px 14px",background:C.red+"20",color:C.red,border:`1px solid ${C.red}40`,borderRadius:"10px",cursor:"pointer",fontWeight:600,fontSize:"13px",alignSelf:"flex-end"}}>✕ مسح الفلاتر</button>}
              </div>
            </div>

            {/* Results count */}
            <div style={{padding:"8px 12px",textAlign:"right",fontSize:"13px",color:C.textDim,flexShrink:0,borderBottom:`1px solid ${C.border}`}}>
              عرض <span style={{color:C.accent,fontWeight:700}}>{visibleInMap.length}</span> قطعة {mapBounds?"في نطاق الخريطة":""}
            </div>

            {/* Scrollable list */}
            <div style={{flex:1,overflowY:"auto",padding:"12px",display:"flex",flexDirection:"column",gap:"12px"}}>
              {visibleInMap.map(lot=><PlotCard key={lot.id} lot={lot} isSelected={lot.ref===selectedRef} onSelect={setSelectedRef}/>)}
              {visibleInMap.length===0&&(
                <div style={{textAlign:"center",padding:"40px 20px",color:C.textMuted}}>
                  <div style={{fontSize:"40px",marginBottom:"12px"}}>🔍</div>
                  <div style={{fontSize:"16px",fontWeight:600}}>لا توجد نتائج</div>
                  <div style={{fontSize:"13px",marginTop:"6px"}}>جرّب تحريك الخريطة أو تغيير الفلاتر</div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      <AddPlotModal open={showAdd} onClose={()=>setShowAdd(false)}/>
    </div>
  );
}
